using System.Collections.Generic;
public static class RideReceiptSummary {
 public static int InitialFare(PassengerResult r){return r.initialFare>0?r.initialFare:r.quoted;}
 static string Signed(int value){return (value>0?"+":"")+value.ToString("N0");}
 public static string Money(PassengerResult r){int initial=InitialFare(r);return (r.farePolicyVersion>=2?"최초 예상 운임  ":"제시 운임  ")+initial.ToString("N0")+"원\n보너스  "+Signed(r.paid-initial)+"원\n"+(r.farePolicyVersion>=2?"실수령  ":"최종 운임  ")+r.paid.ToString("N0")+"원";}
 public static string Rule(PassengerResult r){if(string.IsNullOrEmpty(r.bonusReason))return "";bool late=r.baseFare==0&&r.quoted>0;string bonusReason=late?"기한 초과 0원":r.satisfaction>=r.required?"지급":"0원";if(r.farePolicyVersion>=2){int gap=System.Math.Max(0,r.required-r.satisfaction);string baseReason=late?"기한 초과 0원":gap==0?"전액":"미달 "+gap+"점 · 감액 "+System.Math.Max(0,(r.farePolicyVersion>=3?r.drivingAdjustedFare:r.quoted)-r.baseFare).ToString("N0")+"원";return "기본 운임: 승객 만족도 S "+r.satisfaction+" / 요구 R "+r.required+" → "+baseReason+"\n보너스: 승객 만족도 S "+r.satisfaction+" / 요구 R "+r.required+" → "+bonusReason;}string oldBase=late?"기한 초과 0원":r.score>=r.required?"100%":"70%";return "기본 운임: 운전 만족도 M "+r.score+" / 요구 R "+r.required+" → "+oldBase+"\n보너스: 승객 만족도 S "+r.satisfaction+" / 요구 R "+r.required+" → "+bonusReason;}
 public static string History(PassengerResult r){if(r.farePolicyVersion>=3){int initial=InitialFare(r);return "원약정  "+r.quoted.ToString("N0")+"원 (최초 예상 "+initial.ToString("N0")+"원)\n승차 운전 점수 "+r.boardingDrivingScore+" · 보정 "+Signed(r.drivingAdjustedFare-r.quoted)+"원 → "+r.drivingAdjustedFare.ToString("N0")+"원\n"+(r.paid==0?"시간 초과 · 운임/보너스 없음":"만족도 감액 "+Signed(r.baseFare-r.drivingAdjustedFare)+" · 보너스 "+Signed(r.bonus))+"\n실수령  "+r.paid.ToString("N0")+"원";}if(r.farePolicyVersion<2)return "기본 운임 "+r.baseFare.ToString("N0")+"원 + 보너스 "+r.bonus.ToString("N0")+"원 = "+r.paid.ToString("N0")+"원";int gap=System.Math.Max(0,r.required-r.satisfaction);int deduction=r.paid==0?0:System.Math.Max(0,(r.farePolicyVersion>=3?r.drivingAdjustedFare:r.quoted)-r.baseFare);return "요구 미달 "+gap+"점 · 감액 "+deduction.ToString("N0")+"원\n기본 운임 "+r.baseFare.ToString("N0")+"원 + 보너스 "+r.bonus.ToString("N0")+"원 = "+r.paid.ToString("N0")+"원";}
 public static string Factors(PassengerResult r){
  var lines=new List<string>();if(r.cleanBonus!=0)lines.Add(ScoreFeedback.Text("청결",r.cleanBonus));if(r.driveDelta!=0)lines.Add(ScoreFeedback.Text("주행",r.driveDelta));if(r.satisfactionDelta!=0)lines.Add(ScoreFeedback.Text(r.satisfactionDelta>0?"요청 이행":"요청 미이행",r.satisfactionDelta));if(r.comfortDelta!=0)lines.Add(ScoreFeedback.Text("안정 주행 안심",r.comfortDelta));if(r.timeDelta!=0)lines.Add(ScoreFeedback.Text("도착 시간",r.timeDelta));return lines.Count==0?"만족도 변화 없음":string.Join("\n",lines.ToArray());
 }
}
